@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.nt-hd{position:absolute;left:90px;right:90px;top:250px;font-size:100px;font-weight:var(--rf-heading-weight);letter-spacing:-.045em;line-height:.95}
.nts{position:absolute;left:70px;right:70px;top:640px;display:flex;flex-direction:column;gap:26px}
.nt{display:flex;gap:28px;align-items:center;padding:32px;border-radius:40px;background:var(--rf-surface);border:2px solid color-mix(in srgb,var(--rf-text) 8%,transparent);animation:nt-in .8s cubic-bezier(.16,1,.3,1) both}
@keyframes nt-in{from{transform:translateY(-60px);opacity:0}}
.nt .bm{flex:none;border-radius:22px}
.nt>div{flex:1}
